][j] = 0\n\t\telse:\n\t\t\tL[i][j] = L[i][j - 1] + 1\nfor i in range(1, H + 1):\n\tfor j in range(W, 0, -1):\n\t\tif grid[i][j] == '.':\n\t\t\tR[i][j] = 0\n\t\telse:\n\t\t\tR[i][j] = R[i][j + 1] + 1\nfor j in range(1, W + 1):\n\tfor i in range(1, H + 1):\n\t\tif grid[i][j] == '.':\n\t\t\tU[i][j] = 0\n\t\telse:\n\t\t\tU[i][j] = U[i - 1][j] + 1\nfor j in range(1, W + 1):\n\tfor i in range(H, 0, -1):\n\t\tif grid[i][j] == '.':\n\t\t\tD[i][j] = 0\n\t\telse:\n\t\t\tD[i][j] = D[i + 1][j] + 1\nfor i in range(1, H + 1):\n\tfor j in range(1, W + 1):\n\t\tif grid[i][j] == '*':\n\t\t\tcheck(i, j)\nfor i in range(1, H + 1):\n\tfor j in range(W + 1):\n\t\timosw[i][j + 1] += imosw[i][j]\nfor j in range(1, W + 1):\n\tfor i in range(H + 1):\n\t\timosh[i + 1][j] += imosh[i][j]\nif check2():\n\tprint(len(ans))\n\t[print(h, w, sz) for (h, w, sz) in ans]\nelse:\n\tprint(-1)"
