user_prompt:
请为当前规则生成一个规划候选。
要求：
- 先判断该规则是否适用，再决定是否继续规划。
- 必须输出完整 new_schema，不要只写自然语言摘要。
- `difference_plan.changed_axes` 必须与 new_schema 的真实变化保持一致。
- 所有参数、输入特性、结构变化和不变量承诺都必须 materialize 到四元组字段里。
- `new_schema` 只能包含约定字段，不要附带任何额外键。
- `algorithmic_delta_claim.new_proof_obligation` 表示新增正确性证明，不要把它写成泛泛的难度评价。
- 必须应用当前规则声明的全部 `helpers`，并把它们完整写入 `applied_helpers`。
- `applied_helpers` 中的每一项都要写清它作用到哪些变化轴、改变了哪些 schema 部分、怎样抬高创新度、怎样抬高难度。
- 如果模式是 same_family_fusion，`shared_core_summary` 和三个 shared_core_anchors 不能为空。
- 如果提供了 `revision_context`，要优先修复其中涉及结构差异、目标定义、规则落地和反换皮风险的问题，并保留 `strengths_to_keep`。
- 若 `revision_context` 包含 `revision_history` 或 `revision_summary`，必须综合此前所有轮次的有用信息，不要只依据最近一轮的修订建议。
- 如果你认为该规则不适用或只能做浅改，请返回失败状态，不要硬套。

{
  "mode": "single_seed_extension",
  "rule": {
    "id": "feasibility_to_extremal_threshold",
    "family": "threshold_optimization",
    "audit_tags": [
      "single_seed",
      "threshold",
      "extremal_value"
    ],
    "handler": "feasibility_to_extremal_threshold",
    "enabled": true,
    "summary": "把判定或可行性问题扩展为求最小阈值、最大容量或临界参数的优化题。",
    "eligibility": {
      "required_seed_properties": [
        "原题可行性随某个参数具有清晰的单调性或分层结构",
        "阈值变化会改变主约束的可行区域"
      ],
      "forbidden_seed_properties": [
        "没有自然参数可优化",
        "阈值只是在原判定外层做机械二分"
      ]
    },
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "feasibility_to_extremal_threshold",
      "target_shift": "从判断是否可行改成求临界阈值",
      "new_obligation": "定义阈值、可行区域和临界性证明"
    },
    "helpers": [
      {
        "id": "threshold_parameterization",
        "summary": "把原可行性条件参数化成可搜索的临界阈值。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让目标从真假判断变成极值求解。",
        "difficulty_role": "要求算法处理阈值与可行性的耦合关系。",
        "prompt_guidance": [
          "阈值必须进入核心约束的定义。",
          "目标必须要求输出最小或最大临界参数。"
        ],
        "redlines": [
          "不能只是把 Yes/No 改成 0/1。",
          "不能让阈值脱离主约束。"
        ]
      },
      {
        "id": "monotone_boundary_invariant",
        "summary": "补出支撑临界值正确性的单调或边界不变量。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "把可行性结构提升为边界定位问题。",
        "difficulty_role": "要求证明临界值两侧语义不同且可判定。",
        "prompt_guidance": [
          "说明阈值变化如何影响可行集合。",
          "不变量要支撑边界存在性或唯一性。"
        ],
        "redlines": [
          "不能只有经验性单调描述。",
          "不能省略边界正确性责任。"
        ]
      },
      {
        "id": "extremal_answer_contract",
        "summary": "把输出责任锁定为临界值及其可验证含义。",
        "must_realize_in": [
          "objective",
          "invariant"
        ],
        "target_axes": [
          "O",
          "V"
        ],
        "innovation_role": "让答案成为带证明语义的极值参数。",
        "difficulty_role": "要求解法同时证明达到与不可突破。",
        "prompt_guidance": [
          "目标应说明阈值为何是最小或最大。",
          "不变量应覆盖阈值的达成性和极限性。"
        ],
        "redlines": [
          "不能只输出任意可行参数。",
          "不能把极值证明留给备注。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "阈值必须改变主求解目标",
        "阈值必须进入核心约束",
        "必须说明临界性不变量"
      ]
    },
    "examples": {
      "positive": "把判断是否存在合法方案改成求允许合法方案存在的最小容量。",
      "negative": "原题判定外面简单套一层二分但约束语义不变。"
    },
    "failure_templates": {
      "not_applicable": "这道种子题缺少自然临界参数，无法稳定扩成阈值优化题。",
      "difference_insufficient": "阈值目标没有改变主约束或证明义务，只是包装原判定。"
    },
    "planner_output_contract": {
