        "standard_solution_code": "import sys\nfrom itertools import accumulate\n\ndef input():\n\treturn sys.stdin.readline().strip()\n\ndef list2d(a, b, c):\n\treturn [[c] * b for i in range(a)]\n\ndef list3d(a, b, c, d):\n\treturn [[[d] * c for j in range(b)] for i in range(a)]\n\ndef list4d(a, b, c, d, e):\n\treturn [[[[e] * d for j in range(c)] for j in range(b)] for i in range(a)]\n\ndef ceil(x, y=1):\n\treturn int(-(-x // y))\n\ndef INT():\n\treturn int(input())\n\ndef MAP():\n\treturn map(int, input().split())\n\ndef LIST(N=None):\n\treturn list(MAP()) if N is None else [INT() for i in range(N)]\n\ndef Yes():\n\tprint('Yes')\n\ndef No():\n\tprint('No')\n\ndef YES():\n\tprint('YES')\n\ndef NO():\n\tprint('NO')\nINF = 10 ** 18\nMOD = 10 ** 9 + 7\n\ndef build_grid(H, W, intv, _type, space=True, padding=False):\n\tif space:\n\t\t_input = lambda : input().split()\n\telse:\n\t\t_input = lambda : input()\n\t_list = lambda : list(map(_type, _input()))\n\tif padding:\n\t\toffset = 1\n\telse:\n\t\toffset = 0\n\tgrid = list2d(H + offset * 2, W + offset * 2, intv)\n\tfor i in range(offset, H + offset):\n\t\trow = _list()\n\t\tfor j in range(offset, W + offset):\n\t\t\tgrid[i][j] = row[j - offset]\n\treturn grid\n(H, W) = MAP()\ngrid = build_grid(H, W, '#', str, space=0, padding=1)\nans = []\nimosw = list2d(H + 2, W + 2, 0)\nimosh = list2d(H + 2, W + 2, 0)\n\ndef check(i, j):\n\tsz = min(L[i][j], R[i][j], U[i][j], D[i][j])\n\tif sz > 1:\n\t\timosw[i][j - sz + 1] += 1\n\t\timosw[i][j + sz] -= 1\n\t\timosh[i - sz + 1][j] += 1\n\t\timosh[i + sz][j] -= 1\n\t\tans.append((i, j, sz - 1))\n\ndef check2():\n\tfor i in range(1, H + 1):\n\t\tfor j in range(1, W + 1):\n\t\t\tif grid[i][j] == '*' and (not imosw[i][j]) and (not imosh[i][j]):\n\t\t\t\treturn False\n\treturn True\nL = list2d(H + 2, W + 2, 0)\nR = list2d(H + 2, W + 2, 0)\nU = list2d(H + 2, W + 2, 0)\nD = list2d(H + 2, W + 2, 0)\nfor i in range(1, H + 1):\n\tfor j in range(1, W + 1):\n\t\tif grid[i][j] == '.':\n\t\t\tL[i][j] = 0\n\t\telse:\n\t\t\tL[i][j] = L[i][j - 1] + 1\nfor i in range(1, H + 1):\n\tfor j in range(W, 0, -1):\n\t\tif grid[i][j] == '.':\n\t\t\tR[i][j] = 0\n\t\telse:\n\t\t\tR[i][j] = R[i][j + 1] + 1\nfor j in range(1, W + 1):\n\tfor i in range(1, H + 1):\n\t\tif grid[i][j] == '.':\n\t\t\tU[i][j] = 0\n\t\telse:\n\t\t\tU[i][j] = U[i - 1][j] + 1\nfor j in range(1, W + 1):\n\tfor i in range(H, 0, -1):\n\t\tif grid[i][j] == '.':\n\t\t\tD[i][j] = 0\n\t\telse:\n\t\t\tD[i][j] = D[i + 1][j] + 1\nfor i in range(1, H + 1):\n\tfor j in range(1, W + 1):\n\t\tif grid[i][j] == '*':\n\t\t\tcheck(i, j)\nfor i in range(1, H + 1):\n\tfor j in range(W + 1):\n\t\timosw[i][j + 1] += imosw[i][j]\nfor j in range(1, W + 1):\n\tfor i in range(H + 1):\n\t\timosh[i + 1][j] += imosh[i][j]\nif check2():\n\tprint(len(ans))\n\t[print(h, w, sz) for (h, w, sz) in ans]\nelse:\n\tprint(-1)"
