messages.content:
请在当前规则集中选择最适合当前 schema 的规则。
要求：
- 目标是在保证可落地的前提下，让生成题的创新度和难度尽可能高。
- 如果某条规则只会导致浅改、换皮、后处理增强或伪融合，不要选择它。
- `selection_reason` 要直接说明为什么它优于其余规则。
- 优先返回 `ranked_rule_ids`，按推荐尝试顺序排列前 2 到 3 条规则；`selected_rule_id` 保留为第一推荐项。
- `innovation_reason` 要说明它会把哪些核心义务拉离原题。
- `difficulty_reason` 要说明它会在哪个主求解责任上抬高难度。
- `risk_reason` 要说明主要风险；如果风险可控，也要明确写出来。
- 如果提供了 `revision_context`，要优先修复其中涉及规则选择、结构差异和反换皮风险的问题，并保留 `strengths_to_keep`。
- 若 `revision_context` 包含 `revision_history` 或 `revision_summary`，必须综合此前所有轮次的有用信息，不要只依据最近一轮的修订建议。
- 如果没有规则满足条件，返回失败状态，不要勉强挑选。

{
  "mode": "single_seed_extension",
  "available_rules": [
    {
      "id": "existence_to_counting",
      "family": "objective_upgrade",
      "audit_tags": [
        "single_seed",
        "counting",
        "deduplication"
      ],
      "handler": "existence_to_counting",
      "enabled": true,
      "summary": "把存在性或单一最优值问题改成一个对象明确、去重规则明确的计数题。",
      "eligibility": {
        "required_seed_properties": [
          "解空间有限",
          "不同解之间的等价关系能说清楚",
          "可以按某种单元拆分并汇总"
        ],
        "forbidden_seed_properties": [
          "解空间天然无限",
          "去重规则说不清楚"
        ]
      },
      "required_axis_changes": {
        "must_change": [
          "O",
          "C",
          "V"
        ]
      },
      "core_transformation": {
        "primary_operator": "existence_to_counting",
        "target_shift": "从存在性或最优值改成计数",
        "new_obligation": "定义清楚计数对象、有限性和去重规则"
      },
      "helpers": [
        {
          "id": "counting_unit_definition",
          "summary": "明确计数对象、等价关系与不同答案口径。",
          "must_realize_in": [
            "core_constraints",
            "objective",
            "invariant"
          ],
          "target_axes": [
            "C",
            "O",
            "V"
          ],
          "innovation_role": "把原题答案换成对象明确的计数结果。",
          "difficulty_role": "要求解法处理等价类和有限性证明。",
          "prompt_guidance": [
            "把计数对象直接写进目标定义。",
            "把去重口径写进约束或不变量。"
          ],
          "redlines": [
            "不能只补一个模数。",
            "不能不定义什么算不同答案。"
          ]
        },
        {
          "id": "state_factorization",
          "summary": "把解空间拆成可汇总的计数单元。",
          "must_realize_in": [
            "core_constraints",
            "invariant"
          ],
          "target_axes": [
            "C",
            "V"
          ],
          "innovation_role": "让计数从主状态组织方式中自然长出来。",
          "difficulty_role": "要求解法在分解与汇总层面重建主状态。",
          "prompt_guidance": [
            "让核心约束说明如何拆成计数单元。",
            "让不变量解释单元之间如何避免重复。"
          ],
          "redlines": [
            "不能保持原状态结构不动。",
            "不能把计数只当成结果后处理。"
          ]
        },
        {
          "id": "counting_obligation_lock",
          "summary": "把计数责任锁进主求解目标而不是附带统计。",
          "must_realize_in": [
            "core_constraints",
            "objective"
          ],
          "target_axes": [
            "C",
            "O"
          ],
          "innovation_role": "把原题主目标替换成新的计数义务。",
          "difficulty_role": "要求算法同时承担计数正确性和去重正确性。",
          "prompt_guidance": [
            "让目标定义主导状态转移。",
            "不要保留原判定主目标再顺手计数。"
          ],
          "redlines": [
            "不能继续由原题判定过程主导。",
            "不能把计数目标放进备注。"
          ]
        }
      ],
      "validation_contract": {
        "hard_checks": [
          "必须说明什么样的解算不同",
          "必须说明为什么可数，或者说明取模方式",
          "必须说明按什么单元拆分和汇总"
        ]
      },
      "examples": {
        "positive": "统计所有满足约束的最优构造数，并定义去重与取模。",
        "negative": "把是否存在改成计数，但状态结构和计数对象都没重新定义。"
      },
      "failure_templates": {
        "not_applicable": "这道种子题没有稳定的有限解空间，或者去重规则说不清楚，不适合改成计数题。",
        "difference_insufficient": "改成计数之后没有带来明显的新责任，看起来只是换了答案形式。"
      },
      "planner_output_contract": {
        "required_fields": [
          "eligibility_reason",
          "core_transformation_summary",
          "difference_plan",
          "new_schema",
          "algorithmic_delta_claim",
          "anti_shallow_rationale",
          "applied_helpers"
        ]
      }
    },
    {
      "id": "forward_solution_to_inverse_design",
      "family": "inverse_design",
      "audit_tags": [
        "single_seed",
        "inverse_problem",
        "minimal_edit"
      ],
      "handler": "forward_solution_to_inverse_design",
      "enabled": true,
      "summary": "把正向求解题扩展为给定目标后的最小修改、参数反推或输入设计题。",
      "eligibility": {
        "required_seed_properties": [
          "原题输出或性质可以作为反向目标被指定",
          "存在自然的修改操作或设计自由度"
        ],
        "forbidden_seed_properties": [
          "无法定义可验证的反向目标",
          "修改操作与原核心规律无关"
        ]
      },
      "required_axis_changes": {
        "must_change": [
          "C",
          "O",
          "V"
        ]
      },
      "core_transformation": {
        "primary_operator": "forward_solution_to_inverse_design",
        "target_shift": "从计算给定输入的结果改成设计输入或修改使目标成立",
        "new_obligation": "定义目标结果、允许修改和最小性证明"
      },
      "helpers": [
        {
          "id": "target_result_binding",
          "summary": "把原题结果绑定成新题要达成的反向目标。",
          "must_realize_in": [
            "core_constraints",
            "objective"
          ],
          "target_axes": [
            "C",
            "O"
          ],
          "innovation_role": "让求解方向从正向计算翻转为目标驱动设计。",
          "difficulty_role": "要求算法围绕目标约束反推状态。",
          "prompt_guidance": [
            "目标必须说明要达成的结果性质。",
            "核心约束必须限制目标如何被满足。"
          ],
          "redlines": [
            "不能只是问原答案是否等于给定值。",
            "不能让目标与原核心规律脱节。"
          ]
        },
        {
          "id": "edit_operation_contract",
          "summary": "定义允许修改、构造或参数调整的正式操作集合。",
          "must_realize_in": [
            "core_constraints",
            "invariant"
          ],
          "target_axes": [
            "C",
            "V"
          ],
          "innovation_role": "把反向设计落实到可枚举或可优化的操作空间。",
          "difficulty_role": "要求证明操作序列与目标结果之间的对应关系。",
          "prompt_guidance": [
            "修改操作必须来自原题对象的自然结构。",
            "不变量要解释修改如何影响目标结果。"
          ],
          "redlines": [
            "不能发明无关操作。",
            "不能让修改只改变叙事外观。"
          ]
        },
        {
          "id": "minimality_or_certificate_lock",
          "summary": "要求输出最小修改代价或可验证设计证据。",
          "must_realize_in": [
            "objective",
            "invariant"
          ],
          "target_axes": [
            "O",
            "V"
          ],
          "innovation_role": "让答案承担最小性或构造正确性责任。",
          "difficulty_role": "要求算法证明不能用更少修改达成目标。",
          "prompt_guidance": [
            "输出目标应包含最小代价或具体设计。",
            "不变量要支持下界或正确性证明。"
          ],
          "redlines": [
            "不能只输出任意可行修改。",
            "不能省略最小性证明责任。"
          ]
        }
      ],
      "validation_contract": {
        "hard_checks": [
          "反向目标必须来自原题结果语义",
          "修改操作必须与原核心对象相关",
          "必须承担最小性或设计正确性责任"
        ]
      },
      "examples": {
        "positive": "给定目标答案，求最少修改几个元素使原性质成立。",
        "negative": "随意添加一种与原题无关的操作来构造任意结果。"
      },
