raw_response.validate_test_input_code:
def validate_test_input(input_string):
    try:
        lines = input_string.strip().split('\n')
        if len(lines) != 2:
            return False
        s1, s2 = lines[0], lines[1]
        for s in (s1, s2):
            if len(s) > 15 or len(s) == 0:
                return False
            # 检查字符集
            for ch in s:
                if ch not in '0123456789.()':
                    return False
            # 简单解析：必须有整数部分，可能有点和括号
            # 找小数点和括号位置
            has_dot = '.' in s
            has_lbr = '(' in s
            has_rbr = ')' in s
            # 括号必须成对
            if has_lbr != has_rbr:
                return False
            if has_lbr:
                if s.count('(') != 1 or s.count(')') != 1:
                    return False
                lbr_pos = s.index('(')
                rbr_pos = s.index(')')
                if lbr_pos > rbr_pos:
                    return False
                if rbr_pos - lbr_pos <= 1:  # 括号内至少1个数字
                    return False
                repeat_part = s[lbr_pos+1:rbr_pos]
                if len(repeat_part) < 1 or len(repeat_part) > 4:
                    return False
                for ch in repeat_part:
                    if not ch.isdigit():
                        return False
                # 小数点必须在左括号之前
                if has_dot:
                    dot_pos = s.index('.')
                    if dot_pos > lbr_pos:
                        return False
                # 括号后不应有其他字符
                if rbr_pos != len(s)-1:
                    return False
                # 整数部分和非重复部分
                if has_dot:
                    dot_pos = s.index('.')
                    int_part = s[:dot_pos]
                    non_repeat_part = s[dot_pos+1:lbr_pos]
                else:
                    int_part = s[:lbr_pos]
                    non_repeat_part = ''
            else:
                # 无括号
                if has_dot:
                    dot_pos = s.index('.')
                    int_part = s[:dot_pos]
                    non_repeat_part = s[dot_pos+1:]
                else:
                    int_part = s
                    non_repeat_part = ''

            # 整数部分验证
            if len(int_part) < 1 or len(int_part) > 4:
                return False
            for ch in int_part:
                if not ch.isdigit():
                    return False
            # 不能以"00"开头
            if int_part.startswith('00'):
                return False

            # 非重复部分（如果有小数点）长度0~4，全是数字
            if has_dot:
                if len(non_repeat_part) > 4:
                    return False
                for ch in non_repeat_part:
                    if not ch.isdigit():
                        return False
            else:
                # 没有点，则不能有非重复部分或者括号，但上面已处理。如果既无点也无括号，就是纯整数，已处理。
                pass
        return True
    except Exception:
        return False

