def solve(input_str):
    lines = input_str.strip().split('\\n')
    s1 = lines[0].strip()
    s2 = lines[1].strip()
    n1, n2 = len(s1), len(s2)
    dp = [[0]*(n2+1) for _ in range(n1+1)]
    for i in range(n1+1):
        dp[i][0] = i
    for j in range(n2+1):
        dp[0][j] = j
    for i in range(1, n1+1):
        for j in range(1, n2+1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
    dist = dp[n1][n2]
    out = str(dist) + '\\n' + s2 + '\\n' + s2
    return out

