import heapq
import re

PRECISION = 10

def parse(s):
    """解析字符串为整数部分、非重复部分、重复部分"""
    if '(' in s:
        idx_dot = s.index('.')
        idx_lp = s.index('(')
        idx_rp = s.index(')')
        int_part = s[:idx_dot]
        non_rep = s[idx_dot+1:idx_lp]
        rep = s[idx_lp+1:idx_rp]
        has_bracket = True
    elif '.' in s:
        idx_dot = s.index('.')
        int_part = s[:idx_dot]
        non_rep = s[idx_dot+1:]
        rep = None
        has_bracket = False
    else:
        # 无小数点，视为整数
        int_part = s
        non_rep = ''
        rep = None
        has_bracket = False
    return int_part, non_rep, rep, has_bracket

def is_valid(s):
    """检查字符串是否符合题目格式"""
    # 基本字符检查
    if not re.match(r'^[0-9.()]*$', s):
        return False
    # 解析各部分
    try:
        int_part, non_rep, rep, has_bracket = parse(s)
    except:
        return False
    # 整数部分长度 1-4
    if len(int_part) < 1 or len(int_part) > 4:
        return False
    # 不能以两个以上的零开头
    if len(int_part) >= 2 and int_part[:2] == '00':
        return False
    # 如果有小数点，非重复部分长度 0-4
    if '.' in s:
        if len(non_rep) > 4:
            return False
        if not re.match(r'^[0-9]*$', non_rep):
            return False
    # 如果有括号
    if has_bracket:
        if '(' not in s or ')' not in s:
            return False
        if len(rep) < 1 or len(rep) > 4:
            return False
        if not re.match(r'^[0-9]*$', rep):
            return False
        # 括号只能有一对，且结构固定
        format_str = int_part + '.' + non_rep + '(' + rep + ')'
        if s != format_str:
            return False
    else:
        # 无括号时，不能有括号字符
        if '(' in s or ')' in s:
            return False
    return True

def expand(s, precision=PRECISION):
    """将字符串展开为小数，返回整数部分和指定长度的小数部分字符串"""
    int_part, non_rep, rep, has_bracket = parse(s)
    if '.' not in s:
        # 没有小数点，0小数
        frac = '0' * precision
        return int_part + '.' + frac
    if not has_bracket:
        # 没有重复节，非重复部分可能短于precision，补零
        if len(non_rep) >= precision:
            frac = non_rep[:precision]
        else:
            frac = non_rep + '0' * (precision - len(non_rep))
    else:
        # 有重复节，拼接
        base = non_rep + rep * ((precision - len(non_rep)) // len(rep) + 1)
        frac = base[:precision]
