                new_s = int_part + '.' + new_non_rep + '(' + new_rep + ')'
                if is_valid(new_s):
                    ops.append(new_s)
    # 3. 删除括号（仅当有括号）
    if has_bracket:
        new_non_rep = non_rep + rep
        if len(new_non_rep) <= 4:
            new_s = int_part + '.' + new_non_rep
            if is_valid(new_s):
                ops.append(new_s)
    # 4. 移动括号（仅当有括号）
    if has_bracket:
        # 向左移动左括号：non_rep 减一位，rep 最前加一位
        if len(non_rep) > 0:
            new_rep = non_rep[-1] + rep
            new_non_rep = non_rep[:-1]
            if len(new_non_rep) <= 4 and len(new_rep) <= 4:
