        # 向右移动左括号：non_rep 增一位，rep 减第一位
        if len(rep) >= 2:
            new_non_rep = non_rep + rep[0]
            new_rep = rep[1:]
            if len(new_non_rep) <= 4 and len(new_rep) <= 4:
