            return False
    return True

def get_neighbors(s):
    neighbors = []
    # 操作1：替换数字
    for i, ch in enumerate(s):
        if ch.isdigit():
            for nd in '0123456789':
                if nd != ch:
                    new_s = s[:i] + nd + s[i+1:]
                    if is_valid(new_s):
                        neighbors.append(new_s)
    # 操作2：插入括号（仅当无括号）
    if '(' not in s and '.' in s:
        dot = s.index('.')
        int_part = s[:dot]
        dec_part = s[dot+1:]
        for k in range(len(dec_part)):
            non_rep = dec_part[:k]
            rep = dec_part[k:]
            if len(non_rep) <= 4 and len(rep) >= 1 and len(rep) <= 4:
                new_s = int_part + '.' + non_rep + '(' + rep + ')'
                if is_valid(new_s):
                    neighbors.append(new_s)
    # 操作3：删除括号（仅当有括号）
    if '(' in s:
        left = s.index('(')
        right = s.index(')')
        new_s = s[:left] + s[left+1:right] + s[right+1:]
        if is_valid(new_s):
            neighbors.append(new_s)
    # 操作4：移动左括号
    if '(' in s:
        left = s.index('(')
        right = s.index(')')
        # 向左移动一位
        if left > 0:
            new_s = s[:left-1] + '(' + s[left-1] + s[left+1:right] + ')' + s[right+1:]
            if is_valid(new_s):
                neighbors.append(new_s)
        # 向右移动一位
        if left + 1 < right:  # 右括号在右侧，且保证重复部分至少一位
            new_s = s[:left] + s[left+1] + '(' + s[left+2:right] + ')' + s[right+1:]
            if is_valid(new_s):
                neighbors.append(new_s)
    return neighbors

def bfs_edit(source, target):
    if source == target:
        return 0
    visited = set()
    visited.add(source)
    q = deque()
    q.append((source, 0))
    while q:
        cur, cost = q.popleft()
        for nxt in get_neighbors(cur):
            if nxt == target:
                return cost + 1
            if nxt not in visited:
                visited.add(nxt)
                q.append((nxt, cost + 1))
    return INF

def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return ''
    A = lines[0].strip()
    B = lines[1].strip()
    if A == B:
        return '0\n' + A + '\n' + B
    cost_AtoB = bfs_edit(A, B)
    cost_BtoA = bfs_edit(B, A)
    if cost_AtoB <= cost_BtoA:
        # 将A改成B的形式，输出B和B
        return str(cost_AtoB) + '\n' + B + '\n' + B
    else:
        return str(cost_BtoA) + '\n' + A + '\n' + A

