# 暴力解法完整代码

from fractions import Fraction
from collections import deque


def value(s: str) -> Fraction:
    """将编码字符串转换为精确分数"""
    if '(' in s:
        int_part, rest = s.split('.')
        non_rep, rep_with_paren = rest.split('(')
        rep = rep_with_paren.rstrip(')')
    elif '.' in s:
        int_part, non_rep = s.split('.')
        rep = ''
    else:
        int_part = s
        non_rep = ''
        rep = ''

    int_val = int(int_part)
    if not non_rep and not rep:
        return Fraction(int_val, 1)

    if rep:
        L_non = len(non_rep)
        L_rep = len(rep)
        non_val = int(non_rep) if non_rep else 0
        combined_val = int(non_rep + rep)
        denominator = (10 ** L_rep - 1) * (10 ** L_non)
        numerator = combined_val - non_val
        frac = Fraction(numerator, denominator)
        return Fraction(int_val, 1) + frac
    else:
        frac = Fraction(int(non_rep), 10 ** len(non_rep)) if non_rep else Fraction(0, 1)
        return Fraction(int_val, 1) + frac


def is_valid(s: str) -> bool:
    """检查字符串是否符合编码格式"""
    if not s:
        return False
    # 字符集检查
    allowed = set('0123456789.()')
    if any(ch not in allowed for ch in s):
        return False

    # 括号配对
    if '(' in s or ')' in s:
        if s.count('(') != 1 or s.count(')') != 1:
            return False
        if s.index('(') >= s.index(')'):
            return False
        if '.' not in s or s.index('.') >= s.index('('):
            return False

    # 解析各部分
    if '.' in s:
        int_part, dec_part = s.split('.', 1)
        if '(' in dec_part:
            non_rep, mid = dec_part.split('(', 1)
            if not mid.endswith(')'):
                return False
            rep = mid[:-1]
        else:
            non_rep = dec_part
            rep = ''
    else:
        int_part = s
        non_rep = ''
        rep = ''

    # 整数部分
    if not (1 <= len(int_part) <= 4):
        return False
    if not int_part.isdigit():
        return False
    if len(int_part) > 1 and int_part[0] == '0' and int_part[1] == '0':
        return False

    # 非重复部分
    if not (0 <= len(non_rep) <= 4):
        return False
    if non_rep and not non_rep.isdigit():
        return False

    # 重复部分
    if rep != '':
        if not (1 <= len(rep) <= 4):
            return False
        if not rep.isdigit():
            return False
        # 确保右括号在字符串末尾
        if s[-1] != ')':
            return False
    else:
        if ')' in s:
            return False

    # 总长度不超过15（由各部分长度自然保证，这里再显式检查）
    if len(s) > 15:
        return False

    return True


def neighbors(s: str) -> list:
    """生成所有合法的一步操作邻居字符串"""
    res = []
    # 标记类型
    has_dot = '.' in s
    has_paren = '(' in s

    # 找出所有数字字符位置（替换操作）
    digit_positions = [i for i, ch in enumerate(s) if ch.isdigit()]

    # 1. 替换操作
    for pos in digit_positions:
        orig_d = s[pos]
        for new_d in '0123456789':
            if new_d == orig_d:
                continue
            new_s = s[:pos] + new_d + s[pos+1:]
            if is_valid(new_s):
                res.append(new_s)

    # 如果存在括号，类型2：删除括号和移动括号
    if has_paren:
        # 解析
        int_part, rest = s.split('.', 1)
        dec_part = rest
        non_rep, mid = dec_part.split('(', 1)
        rep = mid[:-1]  # 去掉末尾')'

        # 2. 删除括号
        if len(non_rep) + len(rep) <= 4:
            new_s = int_part + '.' + non_rep + rep
            if is_valid(new_s):
                res.append(new_s)

        # 3. 移动左括号：向左移动
        if len(non_rep) >= 1:
            new_non = non_rep[:-1]
            new_rep = non_rep[-1] + rep
            if len(new_non) <= 4 and len(new_rep) <= 4:
                new_s = int_part + '.' + new_non + '(' + new_rep + ')'
                if is_valid(new_s):
                    res.append(new_s)

        # 4. 移动左括号：向右移动
        if len(rep) >= 2:
            new_non = non_rep + rep[0]
            new_rep = rep[1:]
            if len(new_non) <= 4 and len(new_rep) >= 1:
                new_s = int_part + '.' + new_non + '(' + new_rep + ')'
                if is_valid(new_s):
                    res.append(new_s)

    # 如果没有括号但有小数点，类型1：可以插入括号
    if has_dot and not has_paren:
        int_part, non_rep = s.split('.', 1)
        L = len(non_rep)
        if L >= 1:
            # 选择循环节长度从1到L
            for rep_len in range(1, L + 1):
                new_non = non_rep[:-rep_len]
                rep = non_rep[-rep_len:]
                if len(new_non) <= 4 and len(rep) >= 1:
                    new_s = int_part + '.' + new_non + '(' + rep + ')'
                    if is_valid(new_s):
                        res.append(new_s)

    # 如果既无小数点也无括号（纯整数），没有任何插入括号的可能，因为需要小数点

    # 去重并返回
    return list(set(res))


def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    s1 = lines[0].strip()
    s2 = lines[1].strip()

    # 原始相等直接返回
    if value(s1) == value(s2):
        return f"0\n{s1}\n{s2}"

    # 初始化双向 BFS
    dist1 = {s1: 0}
    dist2 = {s2: 0}
    queue1 = deque([s1])
    queue2 = deque([s2])

    # 记录每个方向上，每个数值的最小编辑距离及其示例字符串
    value_min1 = {value(s1): 0}
    example1 = {value(s1): s1}
    value_min2 = {value(s2): 0}
    example2 = {value(s2): s2}

    best_cost = float('inf')
    best_pair = (None, None)

    while queue1 and queue2:
        # 剪枝：如果当前两个队列的最小距离之和已经 >= 最优代价，可以停止
        min_q1 = dist1[queue1[0]]
        min_q2 = dist2[queue2[0]]
        if min_q1 + min_q2 >= best_cost:
            break

        # 选择较小的队列扩展
        if len(queue1) <= len(queue2):
            cur = queue1.popleft()
            d1 = dist1[cur]
            v1 = value(cur)

            # 检查是否与另一方向有相同数值
            if v1 in value_min2:
                total = d1 + value_min2[v1]
                if total < best_cost:
                    best_cost = total
                    best_pair = (cur, example2[v1])

            # 更新本方向的数值最小距离
            if v1 not in value_min1 or d1 < value_min1[v1]:
                value_min1[v1] = d1
                example1[v1] = cur

            # 扩展邻居
            for nxt in neighbors(cur):
                if nxt not in dist1:
                    dist1[nxt] = d1 + 1
                    queue1.append(nxt)
        else:
            cur = queue2.popleft()
            d2 = dist2[cur]
            v2 = value(cur)

            if v2 in value_min1:
                total = d2 + value_min1[v2]
                if total < best_cost:
                    best_cost = total
                    best_pair = (example1[v2], cur)

            if v2 not in value_min2 or d2 < value_min2[v2]:
                value_min2[v2] = d2
                example2[v2] = cur

            for nxt in neighbors(cur):
                if nxt not in dist2:
                    dist2[nxt] = d2 + 1
                    queue2.append(nxt)

        # 若已找到代价为0的解可提前结束（理论上不会进入因为初始不等）
        if best_cost == 0:
            break

    if best_pair[0] is None:
        # 理论上不应发生，但为了安全回退到原串（不会相等）
        return f"{int(best_cost)}\n{s1}\n{s2}"

    return f"{int(best_cost)}\n{best_pair[0]}\n{best_pair[1]}"


