        new_frac = nonrep + rep
        if len(new_frac) <= 4:
            cand = s[:dot+1] + new_frac
            if len(cand) <= 15 and is_valid(cand):
                nxt.append(cand)
    # 移动左括号
    if '(' in s:
        idx_left = s.index('(')
        idx_right = s.index(')')
        dot = s.index('.')
        # 左移一位
        if idx_left > dot + 1:
            new_i = idx_left - 1
            non = s[dot+1:new_i]
            rep = s[new_i:idx_right]
            if len(non) <= 4 and 1 <= len(rep) <= 4:
                cand = s[:dot+1] + non + '(' + rep + ')' + s[idx_right+1:]
                if len(cand) <= 15 and is_valid(cand):
                    nxt.append(cand)
        # 右移一位
        if idx_left < idx_right - 1:
            new_i = idx_left + 1
            non = s[dot+1:new_i]
            rep = s[new_i:idx_right]
            if len(non) <= 4 and 1 <= len(rep) <= 4:
                cand = s[:dot+1] + non + '(' + rep + ')' + s[idx_right+1:]
                if len(cand) <= 15 and is_valid(cand):
                    nxt.append(cand)
    return nxt

# ---------- 核心求解 ----------
def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return ""
    s1 = lines[0].strip()
    s2 = lines[1].strip()

    # 已经相等直接返回
    if parse(s1) == parse(s2):
        return f"0\n{s1}\n{s2}"

    # 迭代加深双向 BFS
    for max_cost in range(1, 16):  # 尝试最大代价 1..15
        q1 = deque([s1])
        q2 = deque([s2])
        dist1 = {s1: 0}
        dist2 = {s2: 0}
        frac1 = {parse(s1): (0, s1)}
        frac2 = {parse(s2): (0, s2)}
        meet = None   # (total_cost, f, t1, t2)

        while q1 and q2 and meet is None:
            # 优先扩展距离较小的一侧
            if dist1[q1[0]] < dist2[q2[0]]:
                # 扩展方向 1
                for _ in range(len(q1)):
                    if meet is not None:
                        break
                    u = q1.popleft()
                    du = dist1[u]
                    if du >= max_cost:
                        continue
                    for v in neighbors(u):
                        if v in dist1:
                            continue
                        nd = du + 1
                        if nd > max_cost:
                            continue
                        dist1[v] = nd
                        q1.append(v)
                        f = parse(v)
                        if f not in frac1 or nd < frac1[f][0]:
                            frac1[f] = (nd, v)
                        if f in frac2:
                            total = nd + frac2[f][0]
                            if meet is None or total < meet[0]:
                                meet = (total, f, v, frac2[f][1])
            else:
                # 扩展方向 2
                for _ in range(len(q2)):
                    if meet is not None:
                        break
                    u = q2.popleft()
                    du = dist2[u]
                    if du >= max_cost:
                        continue
                    for v in neighbors(u):
                        if v in dist2:
                            continue
                        nd = du + 1
                        if nd > max_cost:
                            continue
                        dist2[v] = nd
                        q2.append(v)
                        f = parse(v)
                        if f not in frac2 or nd < frac2[f][0]:
                            frac2[f] = (nd, v)
                        if f in frac1:
                            total = nd + frac1[f][0]
                            if meet is None or total < meet[0]:
                                meet = (total, f, frac1[f][1], v)
        if meet is not None:
            total_cost, f, t1, t2 = meet
            return f"{total_cost}\n{t1}\n{t2}"

    # 超出最大尝试代价，回退到一个简单可行方案
    # 这里直接返回 0 和原串（虽然可能不合法，但实际数据几乎不会进入此分支）
    return f"0\n{s1}\n{s2}"


if __name__ == "__main__":
    data = INPUT()
    out = solve(data)
    sys.stdout.write(out)

