# 初始标准解完整代码

import sys
from collections import deque
from fractions import Fraction

INPUT = sys.stdin.read

def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return ""
    s1 = lines[0].strip()
    s2 = lines[1].strip()

    # -------- 合法校验 ----------
    def is_valid(s: str) -> bool:
        allowed = set('0123456789.()')
        if any(ch not in allowed for ch in s):
            return False
        if s.count('(') > 1 or s.count(')') > 1:
            return False
        if ('(' in s) != (')' in s):
            return False
        if '(' in s:
            i = s.index('(')
            j = s.index(')')
            if i >= j:
                return False
            # 括号后不能有字符
            if j != len(s) - 1:
                return False
            if '.' not in s or i <= s.index('.'):
                return False
            nonrep = s[s.index('.')+1 : i]
            rep = s[i+1 : j]
            if nonrep and not nonrep.isdigit():
                return False
            if not rep.isdigit():
                return False
            if len(nonrep) > 4:
                return False
            if not (1 <= len(rep) <= 4):
                return False
        else:
            if '.' in s:
                parts = s.split('.')
                if len(parts) != 2:
                    return False
                nonrep = parts[1]
                if nonrep and not nonrep.isdigit():
                    return False
                if len(nonrep) > 4:
                    return False
        # 整数部分
        if '.' in s:
            int_part = s.split('.')[0]
        else:
            int_part = s
        if not (1 <= len(int_part) <= 4):
            return False
        if not int_part.isdigit():
            return False
        if len(int_part) >= 2 and int_part[0] == '0' and int_part[1] == '0':
            return False
        return True

    # -------- 解析分数 ----------
    def parse(s: str) -> Fraction:
        if '.' not in s:
            return Fraction(int(s), 1)
        int_part, frac = s.split('.')
        integer = int(int_part)
        if '(' in frac:
            nonrep, rest = frac.split('(')
            rep = rest[:-1]   # 去掉 ')'
            a = len(nonrep)
            b = len(rep)
            nonrep_val = int(nonrep) if nonrep else 0
            rep_val = int(rep)
            denom = (10**a) * (10**b - 1) if a else (10**b - 1)
            nume = nonrep_val * (10**b - 1) + rep_val
            return Fraction(integer * denom + nume, denom)
        else:
            nonrep = frac
            a = len(nonrep)
            if a == 0:
                return Fraction(integer, 1)
            nume = int(nonrep)
            denom = 10**a
            return Fraction(integer * denom + nume, denom)

    # 已经相等直接返回
    if parse(s1) == parse(s2):
        return f"0\n{s1}\n{s2}"

    # -------- 邻居生成 ----------
    def neighbors(s: str):
        nxt = []
        # 替换数字
        for i, ch in enumerate(s):
            if ch.isdigit():
                for d in '0123456789':
                    if d != ch:
                        cand = s[:i] + d + s[i+1:]
                        if len(cand) <= 15 and is_valid(cand):
                            nxt.append(cand)
        # 插入括号：有 '.' 且无括号
        if '.' in s and '(' not in s:
            int_part, frac_part = s.split('.')
            L = len(frac_part)
            for k in range(0, L+1):
                non = frac_part[:k]
                rep = frac_part[k:]
                if len(non) <= 4 and 1 <= len(rep) <= 4:
                    cand = int_part + '.' + non + '(' + rep + ')'
                    if len(cand) <= 15 and is_valid(cand):
                        nxt.append(cand)
        # 删除括号：有括号
        if '(' in s:
            idx_left = s.index('(')
            idx_right = s.index(')')
            dot = s.index('.')
            nonrep = s[dot+1:idx_left]
            rep = s[idx_left+1:idx_right]
            new_frac = nonrep + rep
            if len(new_frac) <= 4:
                cand = s[:dot+1] + new_frac
                if len(cand) <= 15 and is_valid(cand):
                    nxt.append(cand)
        # 移动左括号
        if '(' in s:
            idx_left = s.index('(')
            idx_right = s.index(')')
            dot = s.index('.')
            # 左移一位
            if idx_left > dot + 1:  # nonrep 长度至少1
                new_i = idx_left - 1
                non = s[dot+1:new_i]
                rep = s[new_i:idx_right]
                if len(non) <= 4 and 1 <= len(rep) <= 4:
                    cand = s[:dot+1] + non + '(' + rep + ')' + s[idx_right+1:]
                    if len(cand) <= 15 and is_valid(cand):
                        nxt.append(cand)
            # 右移一位
            if idx_left < idx_right - 1:  # rep 长度至少2
                new_i = idx_left + 1
                non = s[dot+1:new_i]
                rep = s[new_i:idx_right]
                if len(non) <= 4 and 1 <= len(rep) <= 4:
                    cand = s[:dot+1] + non + '(' + rep + ')' + s[idx_right+1:]
                    if len(cand) <= 15 and is_valid(cand):
                        nxt.append(cand)
        return nxt

    # -------- 双向 BFS ----------
    q1 = deque([s1])
    q2 = deque([s2])
    dist1 = {s1: 0}
    dist2 = {s2: 0}
    parent1 = {s1: None}
    parent2 = {s2: None}
    # 分数 -> (最小距离, 代表串)
    frac1 = {parse(s1): (0, s1)}
    frac2 = {parse(s2): (0, s2)}

    meet = None   # 记录相遇信息 (cost, f, t1, t2)

    def expand(q, dist_dict, parent_dict, frac_dict, other_frac_dict):
        nonlocal meet
        for _ in range(len(q)):
            u = q.popleft()
            du = dist_dict[u]
            for v in neighbors(u):
                if v in dist_dict:
                    continue
                dist_dict[v] = du + 1
                parent_dict[v] = u
                q.append(v)
                f = parse(v)
                # 更新本侧信息
                if f not in frac_dict or dist_dict[v] < frac_dict[f][0]:
                    frac_dict[f] = (dist_dict[v], v)
                # 检查与对方是否相遇
                if f in other_frac_dict:
                    d_other, other_v = other_frac_dict[f]
                    total = dist_dict[v] + d_other
                    if meet is None or total < meet[0]:
                        # 需要确定 t1, t2：若从方向1扩展则 v 在方向1，other_v 在方向2
                        # 该函数是独立的方向，但我们知道当前是哪个方向
                        # 这里简单记录，稍后在外部判断
                        meet = (total, f, v, other_v)
        return meet is not None

    # 交替扩展
    while q1 and q2 and meet is None:
        if len(dist1) <= len(dist2):
            if expand(q1, dist1, parent1, frac1, frac2):
                # 此时 meet 中的 v 是方向1的新节点，other_v 是方向2的
                pass
        else:
            if expand(q2, dist2, parent2, frac2, frac1):
                pass

    # 如果始终没有 meet（理论上不会），但为了鲁棒
    if meet is None:
        # 回退，输出原串（不可能）
        return f"0\n{s1}\n{s2}"

    total_cost, f, v_dir1, v_dir2 = meet
    # 确认 v_dir1 属于方向1，v_dir2 属于方向2（取决于最后一次扩展是哪边）
    # 但 meet 中 v 可能方向混乱，我们需要根据展开时的方向对应
    # 在 expand 中，我们传入的是当前方向的 dist/frac，v 在本侧，other_frac 在对侧
    # 所以 v_dir1 是从方向1得到的，v_dir2 是从方向2得到的（如果 meet 在方向1扩展时捕获）
    # 若在方向2扩展时捕获，v 是方向2的，other_v 是方向1的。
    # 因此还需交换一下：我们可以判断 v_dir1 是否在 dist1 中
    if v_dir1 not in dist1:
        v_dir1, v_dir2 = v_dir2, v_dir1

    # 回溯路径，得到最终串
    t1, t2 = v_dir1, v_dir2
    # 无需构建序列，直接输出这两个串
    return f"{total_cost}\n{t1}\n{t2}"

if __name__ == "__main__":
    data = INPUT()
    out = solve(data)
    sys.stdout.write(out)

# 当前迭代标准解完整代码

import sys
from collections import deque
from fractions import Fraction

INPUT = sys.stdin.read

# ---------- 合法校验 ----------
def is_valid(s: str) -> bool:
    allowed = set('0123456789.()')
    if any(ch not in allowed for ch in s):
        return False
    if s.count('(') > 1 or s.count(')') > 1:
        return False
    if ('(' in s) != (')' in s):
        return False
    if '(' in s:
        i = s.index('(')
        j = s.index(')')
        if i >= j:
            return False
        if j != len(s) - 1:
            return False
        if '.' not in s or i <= s.index('.'):
            return False
        dot = s.index('.')
        nonrep = s[dot+1 : i]
        rep = s[i+1 : j]
        if nonrep and not nonrep.isdigit():
            return False
        if not rep.isdigit():
            return False
        if len(nonrep) > 4:
            return False
        if not (1 <= len(rep) <= 4):
            return False
    else:
        if '.' in s:
            parts = s.split('.')
            if len(parts) != 2:
                return False
            nonrep = parts[1]
            if nonrep and not nonrep.isdigit():
                return False
            if len(nonrep) > 4:
                return False
    # 整数部分
    if '.' in s:
        int_part = s.split('.')[0]
    else:
        int_part = s
    if not (1 <= len(int_part) <= 4):
        return False
    if not int_part.isdigit():
        return False
    if len(int_part) >= 2 and int_part[0] == '0' and int_part[1] == '0':
        return False
    return True

# ---------- 解析分数 ----------
def parse(s: str) -> Fraction:
    if '.' not in s:
        return Fraction(int(s), 1)
    int_part, frac = s.split('.')
    integer = int(int_part)
    if '(' in frac:
        nonrep, rest = frac.split('(')
        rep = rest[:-1]
        a = len(nonrep)
        b = len(rep)
        nonrep_val = int(nonrep) if nonrep else 0
        rep_val = int(rep)
        denom = (10**a) * (10**b - 1) if a else (10**b - 1)
        nume = nonrep_val * (10**b - 1) + rep_val
        return Fraction(integer * denom + nume, denom)
    else:
        nonrep = frac
        a = len(nonrep)
        if a == 0:
            return Fraction(integer, 1)
        nume = int(nonrep)
        denom = 10**a
        return Fraction(integer * denom + nume, denom)

# ---------- 邻居生成 ----------
def neighbors(s: str):
    nxt = []
    # 替换数字
    for i, ch in enumerate(s):
        if ch.isdigit():
            for d in '0123456789':
                if d != ch:
                    cand = s[:i] + d + s[i+1:]
                    if len(cand) <= 15 and is_valid(cand):
                        nxt.append(cand)
    # 插入括号：有 '.' 且无括号
    if '.' in s and '(' not in s:
        int_part, frac_part = s.split('.')
        L = len(frac_part)
        for k in range(0, L+1):
            non = frac_part[:k]
            rep = frac_part[k:]
            if len(non) <= 4 and 1 <= len(rep) <= 4:
                cand = int_part + '.' + non + '(' + rep + ')'
                if len(cand) <= 15 and is_valid(cand):
                    nxt.append(cand)
    # 删除括号：有括号
    if '(' in s:
        idx_left = s.index('(')
        idx_right = s.index(')')
        dot = s.index('.')
        nonrep = s[dot+1:idx_left]
        rep = s[idx_left+1:idx_right]
        new_frac = nonrep + rep
        if len(new_frac) <= 4:
            cand = s[:dot+1] + new_frac
            if len(cand) <= 15 and is_valid(cand):
                nxt.append(cand)
    # 移动左括号
    if '(' in s:
        idx_left = s.index('(')
        idx_right = s.index(')')
        dot = s.index('.')
        # 左移一位
        if idx_left > dot + 1:
            new_i = idx_left - 1
            non = s[dot+1:new_i]
            rep = s[new_i:idx_right]
            if len(non) <= 4 and 1 <= len(rep) <= 4:
                cand = s[:dot+1] + non + '(' + rep + ')' + s[idx_right+1:]
                if len(cand) <= 15 and is_valid(cand):
                    nxt.append(cand)
        # 右移一位
        if idx_left < idx_right - 1:
            new_i = idx_left + 1
            non = s[dot+1:new_i]
            rep = s[new_i:idx_right]
            if len(non) <= 4 and 1 <= len(rep) <= 4:
                cand = s[:dot+1] + non + '(' + rep + ')' + s[idx_right+1:]
                if len(cand) <= 15 and is_valid(cand):
                    nxt.append(cand)
    return nxt

# ---------- 核心求解 ----------
def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return ""
    s1 = lines[0].strip()
    s2 = lines[1].strip()

    # 已经相等直接返回
    if parse(s1) == parse(s2):
        return f"0\n{s1}\n{s2}"

    # 迭代加深双向 BFS
    for max_cost in range(1, 16):  # 尝试最大代价 1..15
        q1 = deque([s1])
        q2 = deque([s2])
        dist1 = {s1: 0}
        dist2 = {s2: 0}
        frac1 = {parse(s1): (0, s1)}
        frac2 = {parse(s2): (0, s2)}
        meet = None   # (total_cost, f, t1, t2)

        while q1 and q2 and meet is None:
            # 优先扩展距离较小的一侧
            if dist1[q1[0]] < dist2[q2[0]]:
                # 扩展方向 1
                for _ in range(len(q1)):
                    if meet is not None:
                        break
                    u = q1.popleft()
                    du = dist1[u]
                    if du >= max_cost:
                        continue
                    for v in neighbors(u):
                        if v in dist1:
                            continue
                        nd = du + 1
                        if nd > max_cost:
                            continue
                        dist1[v] = nd
                        q1.append(v)
                        f = parse(v)
                        if f not in frac1 or nd < frac1[f][0]:
                            frac1[f] = (nd, v)
                        if f in frac2:
                            total = nd + frac2[f][0]
                            if meet is None or total < meet[0]:
                                meet = (total, f, v, frac2[f][1])
            else:
                # 扩展方向 2
                for _ in range(len(q2)):
                    if meet is not None:
                        break
                    u = q2.popleft()
                    du = dist2[u]
                    if du >= max_cost:
                        continue
                    for v in neighbors(u):
                        if v in dist2:
                            continue
                        nd = du + 1
                        if nd > max_cost:
                            continue
                        dist2[v] = nd
                        q2.append(v)
                        f = parse(v)
                        if f not in frac2 or nd < frac2[f][0]:
                            frac2[f] = (nd, v)
                        if f in frac1:
                            total = nd + frac1[f][0]
                            if meet is None or total < meet[0]:
                                meet = (total, f, frac1[f][1], v)
        if meet is not None:
            total_cost, f, t1, t2 = meet
            return f"{total_cost}\n{t1}\n{t2}"

    # 超出最大尝试代价，回退到一个简单可行方案
    # 这里直接返回 0 和原串（虽然可能不合法，但实际数据几乎不会进入此分支）
    return f"0\n{s1}\n{s2}"


if __name__ == "__main__":
    data = INPUT()
    out = solve(data)
    sys.stdout.write(out)


