# ---------- 合法校验 ----------
def is_valid(s: str) -> bool:
    allowed = set('0123456789.()')
    if any(ch not in allowed for ch in s):
        return False
    if s.count('(') > 1 or s.count(')') > 1:
        return False
    if ('(' in s) != (')' in s):
        return False
    if '(' in s:
        i = s.index('(')
        j = s.index(')')
        if i >= j:
            return False
        if j != len(s) - 1:
            return False
        if '.' not in s or i <= s.index('.'):
            return False
        dot = s.index('.')
        nonrep = s[dot+1 : i]
        rep = s[i+1 : j]
        if nonrep and not nonrep.isdigit():
            return False
        if not rep.isdigit():
            return False
        if len(nonrep) > 4:
            return False
        if not (1 <= len(rep) <= 4):
            return False
    else:
        if '.' in s:
            parts = s.split('.')
            if len(parts) != 2:
                return False
            nonrep = parts[1]
            if nonrep and not nonrep.isdigit():
                return False
            if len(nonrep) > 4:
                return False
    # 整数部分
    if '.' in s:
        int_part = s.split('.')[0]
    else:
        int_part = s
    if not (1 <= len(int_part) <= 4):
        return False
    if not int_part.isdigit():
        return False
    if len(int_part) >= 2 and int_part[0] == '0' and int_part[1] == '0':
        return False
    return True

