import sys
from collections import deque
from fractions import Fraction

INPUT = sys.stdin.read

# ---------- 合法校验 ----------
def is_valid(s: str) -> bool:
    allowed = set('0123456789.()')
    if any(ch not in allowed for ch in s):
        return False
    if s.count('(') > 1 or s.count(')') > 1:
        return False
    if ('(' in s) != (')' in s):
        return False
    if '(' in s:
        i = s.index('(')
        j = s.index(')')
        if i >= j:
            return False
        if j != len(s) - 1:
            return False
        if '.' not in s or i <= s.index('.'):
            return False
        dot = s.index('.')
        nonrep = s[dot+1 : i]
        rep = s[i+1 : j]
        if nonrep and not nonrep.isdigit():
            return False
        if not rep.isdigit():
            return False
        if len(nonrep) > 4:
            return False
        if not (1 <= len(rep) <= 4):
            return False
    else:
        if '.' in s:
            parts = s.split('.')
            if len(parts) != 2:
                return False
            nonrep = parts[1]
            if nonrep and not nonrep.isdigit():
                return False
            if len(nonrep) > 4:
                return False
    # 整数部分
    if '.' in s:
        int_part = s.split('.')[0]
    else:
        int_part = s
    if not (1 <= len(int_part) <= 4):
        return False
    if not int_part.isdigit():
        return False
    if len(int_part) >= 2 and int_part[0] == '0' and int_part[1] == '0':
        return False
    return True

# ---------- 解析分数 ----------
def parse(s: str) -> Fraction:
    if '.' not in s:
        return Fraction(int(s), 1)
    int_part, frac = s.split('.')
    integer = int(int_part)
    if '(' in frac:
        nonrep, rest = frac.split('(')
        rep = rest[:-1]
        a = len(nonrep)
        b = len(rep)
        nonrep_val = int(nonrep) if nonrep else 0
        rep_val = int(rep)
        denom = (10**a) * (10**b - 1) if a else (10**b - 1)
        nume = nonrep_val * (10**b - 1) + rep_val
        return Fraction(integer * denom + nume, denom)
    else:
        nonrep = frac
        a = len(nonrep)
        if a == 0:
            return Fraction(integer, 1)
        nume = int(nonrep)
        denom = 10**a
        return Fraction(integer * denom + nume, denom)

# ---------- 邻居生成 ----------
def neighbors(s: str):
    nxt = []
    # 替换数字
    for i, ch in enumerate(s):
        if ch.isdigit():
            for d in '0123456789':
                if d != ch:
                    cand = s[:i] + d + s[i+1:]
                    if len(cand) <= 15 and is_valid(cand):
                        nxt.append(cand)
    # 插入括号：有 '.' 且无括号
    if '.' in s and '(' not in s:
        int_part, frac_part = s.split('.')
        L = len(frac_part)
        for k in range(0, L+1):
            non = frac_part[:k]
            rep = frac_part[k:]
            if len(non) <= 4 and 1 <= len(rep) <= 4:
                cand = int_part + '.' + non + '(' + rep + ')'
                if len(cand) <= 15 and is_valid(cand):
                    nxt.append(cand)
    # 删除括号：有括号
    if '(' in s:
        idx_left = s.index('(')
        idx_right = s.index(')')
        dot = s.index('.')
        nonrep = s[dot+1:idx_left]
        rep = s[idx_left+1:idx_right]
        new_frac = nonrep + rep
        if len(new_frac) <= 4:
            cand = s[:dot+1] + new_frac
            if len(cand) <= 15 and is_valid(cand):
                nxt.append(cand)
    # 移动左括号
    if '(' in s:
        idx_left = s.index('(')
        idx_right = s.index(')')
        dot = s.index('.')
        # 左移一位
        if idx_left > dot + 1:
            new_i = idx_left - 1
            non = s[dot+1:new_i]
            rep = s[new_i:idx_right]
            if len(non) <= 4 and 1 <= len(rep) <= 4:
                cand = s[:dot+1] + non + '(' + rep + ')'
                if len(cand) <= 15 and is_valid(cand):
                    nxt.append(cand)
        # 右移一位
        if idx_left < idx_right - 1:
            new_i = idx_left + 1
            non = s[dot+1:new_i]
            rep = s[new_i:idx_right]
            if len(non) <= 4 and 1 <= len(rep) <= 4:
                cand = s[:dot+1] + non + '(' + rep + ')'
                if len(cand) <= 15 and is_valid(cand):
                    nxt.append(cand)
    return nxt

# ---------- 核心求解 ----------
def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return ""
    s1 = lines[0].strip()
    s2 = lines[1].strip()

    # 已经相等直接返回
    if parse(s1) == parse(s2):
        return f"0\n{s1}\n{s2}"

    # 双向 BFS
    q1 = deque([s1])
    q2 = deque([s2])
    dist1 = {s1: 0}
    dist2 = {s2: 0}
    # 记录每个分数在该方向的最优距离和代表字符串
    frac1 = {parse(s1): (0, s1)}
    frac2 = {parse(s2): (0, s2)}
    meet = None   # (total_cost, f, t1, t2)

    while q1 and q2 and meet is None:
        # 优先扩展距离较小的一侧
        if dist1[q1[0]] <= dist2[q2[0]]:
            # 扩展方向 1
            for _ in range(len(q1)):
                if meet is not None:
                    break
                u = q1.popleft()
                du = dist1[u]
                for v in neighbors(u):
                    if v in dist1:
                        continue
                    nd = du + 1
                    dist1[v] = nd
                    q1.append(v)
                    f = parse(v)
                    if f not in frac1 or nd < frac1[f][0]:
                        frac1[f] = (nd, v)
                    if f in frac2:
                        total = nd + frac2[f][0]
                        if meet is None or total < meet[0]:
                            meet = (total, f, v, frac2[f][1])
        else:
            # 扩展方向 2
            for _ in range(len(q2)):
                if meet is not None:
                    break
                u = q2.popleft()
                du = dist2[u]
                for v in neighbors(u):
                    if v in dist2:
                        continue
                    nd = du + 1
                    dist2[v] = nd
                    q2.append(v)
                    f = parse(v)
                    if f not in frac2 or nd < frac2[f][0]:
                        frac2[f] = (nd, v)
                    if f in frac1:
                        total = nd + frac1[f][0]
                        if meet is None or total < meet[0]:
                            meet = (total, f, frac1[f][1], v)

    if meet is None:
        # 理论上总可达，这里兜底
        return f"0\n{s1}\n{s2}"

    total_cost, f, t1, t2 = meet
    return f"{total_cost}\n{t1}\n{t2}"


if __name__ == "__main__":
    data = INPUT()
    out = solve(data)
    sys.stdout.write(out)


