        idx_left = s.index('(')
        idx_right = s.index(')')
        dot = s.index('.')
        # 左移一位
        if idx_left > dot + 1:
            new_i = idx_left - 1
            non = s[dot+1:new_i]
            rep = s[new_i:idx_right]
            if len(non) <= 4 and 1 <= len(rep) <= 4:
                cand = s[:dot+1] + non + '(' + rep + ')'
                if len(cand) <= 15 and is_valid(cand):
                    nxt.append(cand)
        # 右移一位
        if idx_left < idx_right - 1:
            new_i = idx_left + 1
            non = s[dot+1:new_i]
            rep = s[new_i:idx_right]
            if len(non) <= 4 and 1 <= len(rep) <= 4:
                cand = s[:dot+1] + non + '(' + rep + ')'
                if len(cand) <= 15 and is_valid(cand):
