def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return ""
    s1 = lines[0].strip()
    s2 = lines[1].strip()

    # 已经相等直接返回
    if parse(s1) == parse(s2):
        return f"0\n{s1}\n{s2}"

    # 双向 BFS
    q1 = deque([s1])
    q2 = deque([s2])
    dist1 = {s1: 0}
    dist2 = {s2: 0}
    # 记录每个分数在该方向的最优距离和代表字符串
    frac1 = {parse(s1): (0, s1)}
    frac2 = {parse(s2): (0, s2)}
    meet = None   # (total_cost, f, t1, t2)

    while q1 and q2 and meet is None:
        # 优先扩展距离较小的一侧
        if dist1[q1[0]] <= dist2[q2[0]]:
            # 扩展方向 1
            for _ in range(len(q1)):
                if meet is not None:
                    break
                u = q1.popleft()
                du = dist1[u]
                for v in neighbors(u):
                    if v in dist1:
                        continue
                    nd = du + 1
                    dist1[v] = nd
                    q1.append(v)
                    f = parse(v)
                    if f not in frac1 or nd < frac1[f][0]:
                        frac1[f] = (nd, v)
                    if f in frac2:
                        total = nd + frac2[f][0]
                        if meet is None or total < meet[0]:
                            meet = (total, f, v, frac2[f][1])
        else:
            # 扩展方向 2
            for _ in range(len(q2)):
                if meet is not None:
                    break
                u = q2.popleft()
                du = dist2[u]
                for v in neighbors(u):
                    if v in dist2:
                        continue
                    nd = du + 1
                    dist2[v] = nd
                    q2.append(v)
                    f = parse(v)
                    if f not in frac2 or nd < frac2[f][0]:
                        frac2[f] = (nd, v)
                    if f in frac1:
                        total = nd + frac1[f][0]
                        if meet is None or total < meet[0]:
                            meet = (total, f, frac1[f][1], v)

    if meet is None:
        # 理论上总可达，这里兜底
        return f"0\n{s1}\n{s2}"

    total_cost, f, t1, t2 = meet
    return f"{total_cost}\n{t1}\n{t2}"


