                u = q1.popleft()
                du = dist1[u]
                # 剪枝：当前距离已经超过已有最优解
                if meet is not None and du >= meet[0]:
                    continue
                for v in neighbors(u):
                    if v in dist1:
                        continue
                    nd = du + 1
                    dist1[v] = nd
                    q1.append(v)
                    f = parse(v)
                    if f not in frac1 or nd < frac1[f][0]:
                        frac1[f] = (nd, v)
                    if f in frac2:
