        else:
            if dist2[q2[0]] >= MAX_DEPTH:
                break
            # 扩展方向2
            for _ in range(len(q2)):
                if meet is not None:
                    break
                u = q2.popleft()
                du = dist2[u]
                if meet is not None and du >= meet[0]:
                    continue
                for v in neighbors(u):
                    if v in dist2:
                        continue
                    nd = du + 1
                    dist2[v] = nd
                    q2.append(v)
                    f = parse(v)
                    if f not in frac2 or nd < frac2[f][0]:
