请审查该规划是否兑现规则专属合同。
要求：
- `message` 直接概括结论，不要泛泛而谈。
- `errors` 只写真正构成拒绝的规则专属问题；通过时返回空数组。
- `evidence` 必须引用给定 payload、schema 或规则声明中的具体内容。
- 如果规则声明了 `helpers`，要逐条核对 helper 是否全部出现，以及每个 helper 是否兑现了自己的目标变化轴、落点和 redlines。
- 如果不能确认已经兑现规则专属合同，返回 `fail`。

{
  "review_type": "rule_plan_validation",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名反向问题规划审查官，重点确认规划是否把正向求解翻转成目标驱动的最小修改或构造。",
  "review_brief": "确认规划是否定义目标结果、允许操作和最小性证明，而不是只换一种问法验证原答案。",
  "rule_under_review": {
    "id": "forward_solution_to_inverse_design",
    "family": "inverse_design",
    "summary": "把正向求解题扩展为给定目标后的最小修改、参数反推或输入设计题。",
    "audit_tags": [
      "single_seed",
      "inverse_problem",
      "minimal_edit"
    ],
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "forward_solution_to_inverse_design",
      "target_shift": "从计算给定输入的结果改成设计输入或修改使目标成立",
      "new_obligation": "定义目标结果、允许修改和最小性证明"
    },
    "helpers": [
      {
        "id": "target_result_binding",
        "summary": "把原题结果绑定成新题要达成的反向目标。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让求解方向从正向计算翻转为目标驱动设计。",
        "difficulty_role": "要求算法围绕目标约束反推状态。",
        "prompt_guidance": [
          "目标必须说明要达成的结果性质。",
          "核心约束必须限制目标如何被满足。"
        ],
        "redlines": [
          "不能只是问原答案是否等于给定值。",
          "不能让目标与原核心规律脱节。"
        ]
      },
      {
        "id": "edit_operation_contract",
        "summary": "定义允许修改、构造或参数调整的正式操作集合。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "把反向设计落实到可枚举或可优化的操作空间。",
        "difficulty_role": "要求证明操作序列与目标结果之间的对应关系。",
        "prompt_guidance": [
          "修改操作必须来自原题对象的自然结构。",
          "不变量要解释修改如何影响目标结果。"
        ],
        "redlines": [
          "不能发明无关操作。",
          "不能让修改只改变叙事外观。"
        ]
      },
      {
        "id": "minimality_or_certificate_lock",
        "summary": "要求输出最小修改代价或可验证设计证据。",
        "must_realize_in": [
          "objective",
          "invariant"
        ],
        "target_axes": [
          "O",
          "V"
        ],
        "innovation_role": "让答案承担最小性或构造正确性责任。",
        "difficulty_role": "要求算法证明不能用更少修改达成目标。",
        "prompt_guidance": [
          "输出目标应包含最小代价或具体设计。",
          "不变量要支持下界或正确性证明。"
        ],
        "redlines": [
          "不能只输出任意可行修改。",
          "不能省略最小性证明责任。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "反向目标必须来自原题结果语义",
        "修改操作必须与原核心对象相关",
        "必须承担最小性或设计正确性责任"
      ]
    },
    "planner_output_contract": {
      "required_fields": [
        "eligibility_reason",
        "core_transformation_summary",
        "difference_plan",
        "new_schema",
        "algorithmic_delta_claim",
        "anti_shallow_rationale",
        "applied_helpers"
      ]
    },
    "examples": {
      "positive": "给定目标答案，求最少修改几个元素使原性质成立。",
      "negative": "随意添加一种与原题无关的操作来构造任意结果。"
    },
    "failure_templates": {
      "not_applicable": "这道种子题无法定义稳定的反向目标或自然修改操作。",
      "difference_insufficient": "反向设计没有改变主求解方向，只是把原判定换了问法。"
    }
  },
  "source_schema": {
