        "standard_solution_code": "import sys\nmod = 7 + 10 ** 9\n\ndef f_B(m):\n\tif m <= 0:\n\t\treturn 0\n\ta = B >> 1\n\tb = B + 1 >> 1\n\treturn ((B - 1) * pow(B, m - 1, mod) - a * pow(b, m - 1, mod)) % mod\n\ndef F(n, B=10):\n\tb = B >> 1\n\ta = B + 1 >> 1\n\tif B == 2:\n\t\treturn (pow(B, n, mod) - 1 - b * n) % mod\n\tinv = pow(a - 1, mod - 2, mod)\n\treturn (pow(B, n, mod) - 1 - b * inv * (pow(a, n, mod) - 1)) % mod\n\ndef is_irresponsible(x, B=10):\n\tn = len(x)\n\tx = list(reversed(x))\n\ty = list(x)\n\tc = 1\n\tfor i in range(n):\n\t\t(c, y[i]) = divmod(y[i] + c, B)\n\tif c > 0:\n\t\ty.append(c)\n\tfor i in range(n):\n\t\tif x[i] + y[i] >= B:\n\t\t\treturn True\n\treturn False\n\ndef count_irr(d, B=10):\n\tN = len(d)\n\ta = B + 1 >> 1\n\tb = B >> 1\n\tans = 0\n\tidx = N - 1\n\tfor i in range(N):\n\t\tif d[i] >= a:\n\t\t\tidx = i\n\t\t\tbreak\n\tif is_irresponsible(d, B):\n\t\tans = 1\n\tfor i in range(idx + 1):\n\t\tdelta_i = min(d[i], b)\n\t\tif d[i] > delta_i:\n\t\t\tans = (ans + (d[i] - delta_i) * pow(B, N - 1 - i, mod)) % mod\n\t\tif delta_i > 0:\n\t\t\tans = (ans + delta_i * F(N - 1 - i, B)) % mod\n\tfor i in range(idx + 1, N):\n\t\tans = (ans + d[i] * pow(B, N - 1 - i, mod)) % mod\n\treturn ans\n\ndef solve(d, rep, B=10):\n\tN = len(d)\n\ta = B + 1 >> 1\n\tb = B >> 1\n\tans = 0\n\tidx = N\n\tfor i in range(N):\n\t\tif d[i] >= a:\n\t\t\tidx = i\n\t\t\tbreak\n\tif is_irresponsible(d, B) or (2 * d[-1] >= B and rep >= 2 and (len(set(d)) >= 2)):\n\t\tans = 1\n\tinv_B = pow(pow(B, N, mod) - 1, mod - 2, mod)\n\tinv_a = pow(pow(a, N, mod) - 1, mod - 2, mod)\n\tinv = pow(a - 1, mod - 2, mod)\n\tp_B = pow(B, N * rep % (mod - 1), mod) - 1\n\tp_a = pow(a, N * rep % (mod - 1), mod) - 1\n\tif idx <= N - 1:\n\t\tfor i in range(idx + 1):\n\t\t\tdelta_i = min(d[i], b)\n\t\t\tif d[i]:\n\t\t\t\tans = (ans + d[i] * pow(B, N - i - 1, mod) * p_B * inv_B) % mod\n\t\t\tif delta_i:\n\t\t\t\tpp = pow(a, (N * rep - 1 - i) % (mod - 1), mod) - 1\n\t\t\t\tans = (ans - delta_i * (1 + b * pp * inv)) % mod\n\t\tfor i in range(idx + 1, N):\n\t\t\tif d[i]:\n\t\t\t\tans = (ans + d[i] * pow(B, N - i - 1, mod) * p_B * inv_B) % mod\n\telse:\n\t\t(T, D) = (0, 0)\n\t\tfor i in range(N):\n\t\t\tdelta_i = min(d[i], b)\n\t\t\tif d[i]:\n\t\t\t\tans = (ans + d[i] * pow(B, N - 1 - i, mod) * p_B * inv_B) % mod\n\t\t\tif delta_i:\n\t\t\t\tT = (T + delta_i * pow(a, N - i - 1, mod) * p_a * inv_a) % mod\n\t\t\t\tD = (D + delta_i * rep) % mod\n\t\tans = (ans - D - b * inv * (T - D)) % mod\n\treturn ans\n(x, rep) = sys.stdin.readline().strip().split()\nx = list(map(int, x))\nprint(solve(x, int(rep)))"
