          "不能让修改只改变叙事外观。"
        ]
      },
      {
        "id": "minimality_or_certificate_lock",
        "summary": "要求输出最小修改代价或可验证设计证据。",
        "must_realize_in": [
          "objective",
          "invariant"
        ],
        "target_axes": [
          "O",
          "V"
        ],
        "innovation_role": "让答案承担最小性或构造正确性责任。",
        "difficulty_role": "要求算法证明不能用更少修改达成目标。",
        "prompt_guidance": [
          "输出目标应包含最小代价或具体设计。",
          "不变量要支持下界或正确性证明。"
        ],
        "redlines": [
          "不能只输出任意可行修改。",
          "不能省略最小性证明责任。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "反向目标必须来自原题结果语义",
        "修改操作必须与原核心对象相关",
        "必须承担最小性或设计正确性责任"
      ]
    },
    "planner_output_contract": {
      "required_fields": [
        "eligibility_reason",
