      "difference_insufficient": "反向设计没有改变主求解方向，只是把原判定换了问法。"
    }
  },
  "source_schema": {
    "problem_id": "taco_hackerrank_476760348002",
    "source": "hackerrank",
    "input_structure": {
      "type": "composite",
