        }
      ]
    },
    "core_constraints": {
      "constraints": [
        {
          "name": "carry_condition",
          "description": "A number x is called irresponsible if and only if computing x + (x+1) requires a carry operation.",
          "formal": "irresponsible(x) ⇔ carry(x, x+1)",
          "source_sections": [
            "description"
          ]
        },
        {
          "name": "concatenation_construction",
          "description": "The upper bound s is formed by concatenating the decimal string of x exactly n times and interpreting the result as an integer.",
          "formal": "s = int( str(x) repeated n times )",
          "source_sections": [
